1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import org.springframework.web.bind.annotation.RequestParam;
5	import net.officefloor.web.ObjectResponse;
6	
7	/**
8	 * {@code GET /api/invoices/due?invoiceId=<id>} — how much is still left to pay on one invoice: its
9	 * amount (the worked-out sum of its line items, Flyway V13/V14) minus everything paid against it (the
10	 * sum of its payments, Flyway V19). The figure is derived on the server so the money math lives in
11	 * one place, and an invoice with no payments yet is simply its full amount. Wired by
12	 * {@code officefloor/rest/api/invoices/due.GET.yml}.
13	 */
14	public class InvoiceDueGetLogic {
15	
16	    public void service(@RequestParam("invoiceId") Long invoiceId, InvoiceRepository invoices,
17	            PaymentRepository payments, ObjectResponse<InvoiceDueView> response) {
18	        Invoice invoice = invoices.findById(invoiceId).orElse(null);
19	        BigDecimal subtotal = invoice != null ? invoice.getAmount() : BigDecimal.ZERO;
20	        // What is owed is the net total after any discount (Flyway V27) with tax added on top (Flyway
21	        // V28), worked out the one-place way (InvoiceMoney) so the detail figure agrees with the
22	        // dashboard and the statement.
23	        BigDecimal amount = InvoiceMoney.netTotal(subtotal,
24	                invoice != null ? invoice.getDiscountPct() : null,
25	                invoice != null ? invoice.getTaxPct() : null);
26	        BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(invoiceId).stream()
27	                .map(Payment::getAmount)
28	                .reduce(BigDecimal.ZERO, BigDecimal::add);
29	        // The status is worked out from the payments too (see InvoiceStatus), so the detail page
30	        // reads the same one-place rule as the list — no hand-set paid flag. It compares against the
31	        // discounted total, so an invoice is PAID once the payments cover what is actually owed.
32	        String status = InvoiceStatus.derive(invoice != null ? invoice.getStatus() : null, amount,
33	                paid);
34	        response.send(new InvoiceDueView(invoiceId, amount, paid, amount.subtract(paid), status));
35	    }
36	
37	    /**
38	     * What is left to pay on one invoice: its amount, what has been paid, the difference, and the
39	     * status worked out from the payments (SENT / PARTIAL / PAID).
40	     */
41	    public static class InvoiceDueView {
42	        private final long invoiceId;
43	        private final BigDecimal amount;
44	        private final BigDecimal paid;
45	        private final BigDecimal due;
46	        private final String status;
47	
48	        public InvoiceDueView(long invoiceId, BigDecimal amount, BigDecimal paid, BigDecimal due,
49	                String status) {
50	            this.invoiceId = invoiceId;
51	            this.amount = amount;
52	            this.paid = paid;
53	            this.due = due;
54	            this.status = status;
55	        }
56	
57	        public long getInvoiceId() {
58	            return invoiceId;
59	        }
60	
61	        public BigDecimal getAmount() {
62	            return amount;
63	        }
64	
65	        public BigDecimal getPaid() {
66	            return paid;
67	        }
68	
69	        public BigDecimal getDue() {
70	            return due;
71	        }
72	
73	        public String getStatus() {
74	            return status;
75	        }
76	    }
77	}
